pub ghost enum UpdateState<DT: Dispatch> {
    Init { op: DT::WriteOperation },
    Placed { op: DT::WriteOperation, idx: LogIdx },
    Applied { ret: DT::Response, idx: LogIdx },
    Done { ret: DT::Response, idx: LogIdx },
